	/* @Test */
	public void testBasicUnwind()
    {
		addPlugins();

		List<string> files =
			Arrays.asList("kernel32.dll", "expSpin.exe", "ntdll.dll");
		ManagedDomainObject<Trace> mdo = initPrograms("expSpin_lldb", files);

		using (LldbAndTrace conn = startAndSyncLldb(mdo))
{
			traceManager.activateSnap(2);

			waitForPass(() => assertEquals(Boolean.TRUE,
				traceManager.getCurrent().getSnap() == 2));

			checkRtlUserThreadStartUnwindFrom0(2);
			checkMainUnwindFrom0(1);
			checkSleepUnwindFrom0(0);

			conn.success();
		}
	}

